#!/usr/bin/env python3
# managed-by: redesign_v2 kb (v2.4). init_project.py overwrites this file when a newer version ships; do not edit here.
"""kb - card-based project memory: small cards + auto INDEX + section search. Stdlib only, Python 3.8+.

Layout (project root = parent of the .ai folder that holds this file):
  .ai/NOW.md            current state, at most ~10 lines (hand-written by Claude or you)
  .ai/INDEX.md          generated by `build`; one line per card. Do not edit.
  .ai/kb/<type>/<id>.md cards: progress (P-), decision (D-), issue (I-), map (M-), asset (A-)
  .ai/kb.json           optional settings (asset/search folders, Graphify output, limits)
  .ai/archive/          verbatim originals and wrap-up reports; searched, never loaded at start

Commands:
  build                              regenerate .ai/INDEX.md
  search WORDS... [-k 5] [--scope all|cards|docs|archive|graph] [--type T] [--tag X]
                                     section search; prints  path:start-end | heading | snippet
  new TYPE [PATH] [--id ID] [--title T] [--tags a,b] [--related X,Y]
                                     create a card (TYPE: progress|decision|issue|map|asset; PATH for asset)
  check [--coverage DIR] [--strict]  lint cards, links, NOW size, unregistered/changed assets, stale cards;
                                     --coverage: IDs (H1, L3, M7-7b...) found in DIR but in no card/doc
  wrapup                             write a wrap-up report draft to .ai/archive/reports/
  hook-start                         SessionStart hook: print NOW + INDEX (rebuilds INDEX if stale)
  hook-build                         PostToolUse hook: rebuild INDEX when a card or NOW.md was written
"""
from __future__ import annotations

