# ---------------------------------------------------------------- basics
def find_root(arg: str | None) -> Path:
    if arg:
        return Path(arg).resolve()
    here = Path(__file__).resolve().parent
    if here.name == ".ai":
        return here.parent
    return Path.cwd()


def load_cfg(root: Path) -> dict:
    cfg = dict(DEFAULTS)
    p = root / ".ai" / "kb.json"
    if p.exists():
        try:
            cfg.update(json.loads(p.read_text(encoding="utf-8-sig")))
        except ValueError as e:
            print(f"warning: .ai/kb.json unreadable ({e}); using defaults", file=sys.stderr)
    if cfg.get("lang") not in MSG:
        cfg["lang"] = "kr"
    return cfg


def read(p: Path) -> str:
    try:
        return p.read_text(encoding="utf-8-sig", errors="replace")
    except OSError:
        return ""


def write(p: Path, text: str) -> None:
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes((text).encode("utf-8"))


def rel(root: Path, p: Path) -> str:
    try:
        return p.resolve().relative_to(root.resolve()).as_posix()
    except ValueError:
        return p.as_posix()


def today() -> str:
    return dt.date.today().isoformat()


def parse_list(v: str) -> list:
    v = v.strip()
    if v.startswith("[") and v.endswith("]") and not v.startswith("[["):
        v = v[1:-1]
    out = []
    for part in re.split(r",(?![^\[]*\]\])", v):
        part = part.strip().strip("'\"").strip()
        if part:
            out.append(part)
    return out


def parse_card(text: str) -> tuple:
    """Return (meta dict, body str, frontmatter line count). Supports `key: value`, `key: [a, b]`, and `- item` lists."""
    lines = text.splitlines()
    if not lines or lines[0].strip() != "---":
        return {}, text, 0
    meta, key, end = {}, None, None
    for i in range(1, len(lines)):
        ln = lines[i]
        if ln.strip() == "---":
            end = i
            break
        m = re.match(r"^([A-Za-z_][\w-]*):\s*(.*)$", ln)
        if m:
            key = m.group(1)
            meta[key] = m.group(2).strip()
        elif key and re.match(r"^\s*-\s+", ln):
            prev = meta.get(key, "")
            item = re.sub(r"^\s*-\s+", "", ln).strip()
            meta[key] = (prev + ", " if prev else "") + item
    if end is None:
        return {}, text, 0
    for k in ("tags", "related"):
        meta[k] = parse_list(meta.get(k, ""))
    return meta, "\n".join(lines[end + 1:]), end + 1


class Card:
    def __init__(self, path: Path, root: Path):
        self.path = path
        self.text = read(path)
        self.meta, self.body, self.fm_lines = parse_card(self.text)
        self.id = self.meta.get("id", "")
        self.type = self.meta.get("type", "")
        self.title = self.meta.get("title", "")
        self.status = self.meta.get("status", "active") or "active"
        self.updated = self.meta.get("updated", "")
        self.tags = self.meta.get("tags", [])
        self.rel = rel(root, path)
        links = set()
        for r in self.meta.get("related", []):
            links.update(LINK_RE.findall(r) or [r.strip("[]")])
        links.update(LINK_RE.findall(COMMENT_RE.sub("", self.body)))
        sb = self.meta.get("superseded_by", "")
        links.update(LINK_RE.findall(sb) or ([sb] if sb else []))
        self.links = {x.strip() for x in links if x.strip()}


def kb_dir(root: Path) -> Path:
    return root / ".ai" / "kb"


def load_cards(root: Path) -> list:
    d = kb_dir(root)
    if not d.is_dir():
        return []
    return [Card(p, root) for p in sorted(d.rglob("*.md")) if p.is_file()]


# ---------------------------------------------------------------- build
def build(root: Path, cfg: dict, quiet: bool = False) -> Path:
    m = MSG[cfg["lang"]]
    cards = [c for c in load_cards(root) if c.id]
    out = [m["index_head"]]
    act = sum(1 for c in cards if c.status == "active")
    out.append(f"<!-- cards {len(cards)} | active {act} | built {dt.datetime.now().strftime('%Y-%m-%d %H:%M')} -->")
    keep = int(cfg["index_done_keep"])
    for t in TYPES:
        group = [c for c in cards if c.type == t]
        if not group:
            continue
        out.append(f"## {t}")
        live = sorted((c for c in group if c.status == "active"), key=lambda c: (c.updated, c.id), reverse=True)
        old = sorted((c for c in group if c.status != "active"), key=lambda c: (c.updated, c.id), reverse=True)
        if t == "asset":
            kinds = {}
            for c in live:
                kinds.setdefault(c.meta.get("kind", "") or "-", []).append(c)
            for k in sorted(kinds):
                for c in kinds[k]:
                    out.append(f"- [[{c.id}]] {c.title} · {c.meta.get('path', '')}" + (f" ({k})" if k != "-" else ""))
        else:
            for c in live:
                out.append(f"- [[{c.id}]] {c.title}" + (f" · {','.join(c.tags)}" if c.tags else ""))
        for c in old[:keep]:
            out.append(f"- [[{c.id}]] {c.title} · {c.status}")
        if len(old) > keep:
            out.append(m["more"].format(n=len(old) - keep))
    p = root / ".ai" / "INDEX.md"
    write(p, "\n".join(out) + "\n")
    if not quiet:
        print(f"built {rel(root, p)}: {len(cards)} card(s), {act} active, {p.stat().st_size} bytes")
    return p


def index_stale(root: Path) -> bool:
    p = root / ".ai" / "INDEX.md"
    if not p.exists():
        return True
    t = p.stat().st_mtime
    d = kb_dir(root)
    return d.is_dir() and any(q.stat().st_mtime > t for q in d.rglob("*.md"))


# ---------------------------------------------------------------- search
def iter_sources(root: Path, cfg: dict, scope: str):
    """Yield (path, kind) for searchable text files."""
    exts = {e.lower() for e in cfg["text_ext"]}
    excl = [x.replace("\\", "/") for x in cfg.get("search_exclude", [])]
    seen = set()

    def walk(base: Path, kind: str):
        if base.is_file():
            items = [base]
        elif base.is_dir():
            items = sorted(base.rglob("*"))
        else:
            items = []
        for p in items:
            r = rel(root, p)
            if any(r == x or r.startswith(x.rstrip("/") + "/") for x in excl):
                continue
            if p.is_file() and p.suffix.lower() in exts and p.resolve() not in seen:
                seen.add(p.resolve())
                yield p, kind

    ai = root / ".ai"
    if scope in ("all", "cards"):
        yield from walk(kb_dir(root), "card")
        yield from walk(ai / "NOW.md", "now")
        yield from walk(ai / "INTENT.md", "now")
        yield from walk(ai / "intent", "now")
    if scope in ("all", "docs"):
        for d in cfg["search_dirs"]:
            yield from walk(root / d, "doc")
    if scope in ("all", "archive"):
        yield from walk(ai / "archive", "archive")
    graph = root / cfg["graphify_out"]
    if scope == "graph" or (scope == "all" and cfg.get("graph_in_search")):
        yield from walk(graph / "wiki", "graph")
        yield from walk(graph / "GRAPH_REPORT.md", "graph")


def chunks(lines: list, is_card: bool, title: str):
    """Split into (start, end, heading) 1-based inclusive. Cards are one chunk; others split at #..### and every 60 lines."""
    if is_card:
        yield 1, len(lines), title
        return
    start, head = 1, ""
    for i, ln in enumerate(lines, 1):
        m = HEAD_RE.match(ln)
        if (m and i > start) or (i - start >= 60):
            yield start, i - 1, head
            start = i
            head = m.group(1).strip() if m else head
        elif m and i == start:
            head = m.group(1).strip()
    if lines:
        yield start, len(lines), head


PARTICLES = sorted("에서부터 으로부터 에게서 까지 부터 에서 으로 에게 처럼 보다 하고 이나 이며 이랑 라는 이라는 을 를 이 가 은 는 의 에 로 와 과 도 만 랑 며".split(), key=len, reverse=True)


def norm_term(t: str) -> str:
    """Drop one trailing Korean particle so '위젯을' also finds '위젯은' (stem must keep 2+ chars)."""
    if re.search(r"[\uac00-\ud7a3]$", t):
        for p in PARTICLES:
            if t.endswith(p) and len(t) - len(p) >= 2:
                return t[: -len(p)]
    return t


WEIGHT = {"card": 1.3, "now": 1.2, "doc": 1.0, "graph": 0.9, "archive": 0.7}


def search(root: Path, cfg: dict, words: list, k: int, scope: str, typ: str | None, tag: str | None) -> int:
    terms = [norm_term(w.lower()) for w in " ".join(words).split() if w.strip()]
    if not terms:
        print("usage: kb.py search WORDS...")
        return 2
    if typ or tag:
        scope = "cards"
    hits = []
    for p, kind in iter_sources(root, cfg, scope):
        text = read(p)
        lines = text.splitlines()
        title, weight = "", WEIGHT[kind]
        if kind == "card":
            c = Card(p, root)
            if typ and c.type != typ:
                continue
            if tag and tag not in c.tags:
                continue
            title = f"{c.id} {c.title}".strip()
            if c.status != "active":
                weight *= 0.7
        for s, e, head in chunks(lines, kind == "card", title):
            body = "\n".join(lines[s - 1:e]).lower()
            score, matched = 0.0, 0
            for t in terms:
                n = body.count(t)
                if n:
                    matched += 1
                    score += 1 + math.log(n)
                    if t in head.lower():
                        score += 1.5
            if not matched:
                continue
            score *= weight * (matched / len(terms)) ** 2
            snip, best = "", 0
            for j in range(s - 1, e):
                lj = lines[j].lower()
                hit = sum(1 for t in terms if t in lj)
                if hit > best and not lines[j].startswith(("---", "title:", "tags:", "related:")):
                    pos = min(lj.find(t) for t in terms if t in lj)
                    a = max(0, pos - 40)
                    snip, best = ("…" if a else "") + lines[j][a:a + 110].strip(), hit
                    if hit == len(terms):
                        break
            hits.append((score, rel(root, p), s, e, head, snip, kind))
    hits.sort(key=lambda h: -h[0])
    if not hits:
        print("no match")
        return 1
    for sc, path, s, e, head, snip, kind in hits[:k]:
        print(f"{path}:{s}-{e} | {head[:60] or '-'} | {snip}  [{kind} {sc:.1f}]")
    if len(hits) > k:
        print(f"(+{len(hits) - k} more; -k {min(len(hits), k * 2)})")
    return 0


# ---------------------------------------------------------------- new
def slug(s: str) -> str:
    s = re.sub(r"[^A-Za-z0-9]+", "-", s).strip("-").lower()
    return s[:48].strip("-")


def next_id(root: Path, prefix: str) -> str:
    nums = [int(m.group(1)) for c in load_cards(root) for m in [re.match(rf"^{prefix}-(\d+)$", c.id)] if m]
    return f"{prefix}-{(max(nums) + 1) if nums else 1:03d}"


def kind_of(path: str) -> str:
    e = Path(path).suffix.lower().lstrip(".")
    if e in ("png", "jpg", "jpeg", "gif", "webp", "svg"):
        return "image"
    if e in ("ps1", "py", "sh", "bat"):
        return "script"
    if e in ("potx", "dotx"):
        return "template"
    return e or "file"


def new(root: Path, cfg: dict, typ: str, path: str | None, cid: str | None, title: str | None, tags: str, related: str) -> int:
    if typ not in TYPES:
        print(f"error: TYPE must be one of {', '.join(TYPES)}")
        return 2
    prefix = TYPES[typ]
    extra = []
    if typ == "asset":
        if not path:
            print("error: new asset needs PATH (relative to the project root)")
            return 2
        ap = (root / path) if not Path(path).is_absolute() else Path(path)
        if not ap.exists():
            print(f"error: {path} not found")
            return 2
        path = rel(root, ap)
        title = title or ap.stem
        s = slug(Path(path).with_suffix("").as_posix())
        cid = cid or (f"A-{s}" if s and not re.search(r"[^\x00-\x7f]", Path(path).stem) else next_id(root, "A"))
        extra = [f"path: {path}", f"kind: {kind_of(path)}"]
    cid = cid or next_id(root, prefix)
    if not cid.startswith(prefix + "-"):
        print(f"error: {typ} ids start with '{prefix}-' (got {cid})")
        return 2
    if any(c.id == cid for c in load_cards(root)):
        print(f"error: id {cid} already exists")
        return 2
    title = (title or "").strip() or "(제목)"
    rl = ", ".join(f'"[[{x.strip().strip("[]")}]]"' for x in related.split(",") if x.strip()) if related else ""
    tg = ", ".join(t.strip() for t in tags.split(",") if t.strip()) if tags else ""
    fm = ["---", f"id: {cid}", f"type: {typ}", f"title: {title}", "status: active", f"tags: [{tg}]",
          f"updated: {today()}", f"related: [{rl}]"] + extra + ["---"]
    body = MSG[cfg["lang"]]["templates"][typ].format(title=title)
    p = kb_dir(root) / typ / f"{cid}.md"
    write(p, "\n".join(fm) + "\n" + body)
    build(root, cfg, quiet=True)
    print(f"created {rel(root, p)}")
    return 0


# ---------------------------------------------------------------- check
def ignored(name: str, pats: list) -> bool:
    return any(fnmatch.fnmatch(name, p) for p in pats)


def check(root: Path, cfg: dict, coverage: str | None, strict: bool) -> int:
    errs, warns = [], []
    cards = load_cards(root)
    ids = {}
    for c in cards:
        if not c.meta:
            errs.append(f"{c.rel}: no frontmatter (--- ... ---)")
            continue
        for f in ("id", "type", "title"):
            if not c.meta.get(f):
                errs.append(f"{c.rel}: missing '{f}'")
        if c.id and Path(c.rel).stem != c.id:
            errs.append(f"{c.rel}: id '{c.id}' differs from file name")
        if c.type and c.type not in TYPES:
            errs.append(f"{c.rel}: unknown type '{c.type}'")
        elif c.type and c.id and not c.id.startswith(TYPES[c.type] + "-"):
            errs.append(f"{c.rel}: {c.type} id must start with '{TYPES[c.type]}-'")
        if c.status not in STATUSES:
            errs.append(f"{c.rel}: status must be one of {'/'.join(STATUSES)}")
        if c.status == "superseded" and not c.meta.get("superseded_by"):
            errs.append(f"{c.rel}: superseded without superseded_by")
        if c.id in ids:
            errs.append(f"{c.rel}: duplicate id {c.id} (also {ids[c.id]})")
        ids[c.id] = c.rel
        n = len(c.text.splitlines()) - c.fm_lines
        if n > int(cfg["card_max_lines"]):
            warns.append(f"{c.rel}: body {n} lines > {cfg['card_max_lines']} (split into more cards)")
        if c.updated:
            try:
                age = (dt.date.today() - dt.date.fromisoformat(c.updated)).days
                if c.status == "active" and c.type in ("progress", "issue") and age > int(cfg["stale_days"]):
                    warns.append(f"{c.rel}: active but not updated for {age} days")
            except ValueError:
                errs.append(f"{c.rel}: updated must be YYYY-MM-DD")
        if c.type == "asset":
            ap = c.meta.get("path", "")
            if not ap:
                errs.append(f"{c.rel}: asset without path")
            elif not (root / ap).exists():
                errs.append(f"{c.rel}: path {ap} does not exist")
            elif c.updated:
                try:
                    mt = dt.date.fromtimestamp((root / ap).stat().st_mtime)
                    if mt > dt.date.fromisoformat(c.updated):
                        warns.append(f"{c.rel}: {ap} changed on {mt} after card update {c.updated} (refresh summary)")
                except (ValueError, OSError):
                    pass
    inbound = {}
    now_text = read(root / ".ai" / "NOW.md")
    for c in cards:
        for l in c.links:
            if l not in ids:
                errs.append(f"{c.rel}: broken link [[{l}]]")
            inbound[l] = inbound.get(l, 0) + 1
    for l in LINK_RE.findall(COMMENT_RE.sub("", now_text)):
        if l not in ids:
            errs.append(f".ai/NOW.md: broken link [[{l}]]")
        inbound[l] = inbound.get(l, 0) + 1
    for c in cards:
        if c.type in ("decision", "issue", "map") and c.status == "active" and not inbound.get(c.id) and not c.links:
            warns.append(f"{c.rel}: orphan (no links in or out; add related)")
    now_lines = [l for l in now_text.splitlines() if l.strip() and not l.lstrip().startswith(("<!--", "#"))]
    if not now_text:
        warns.append(".ai/NOW.md missing")
    elif len(now_lines) > int(cfg["now_max_lines"]):
        warns.append(f".ai/NOW.md: {len(now_lines)} content lines > {cfg['now_max_lines']}")
    idx = root / ".ai" / "INDEX.md"
    if idx.exists() and idx.stat().st_size > int(cfg["index_max_bytes"]):
        warns.append(f".ai/INDEX.md: {idx.stat().st_size} bytes > {cfg['index_max_bytes']} (mark finished cards done, or archive)")
    registered = {c.meta.get("path", "").replace("\\", "/") for c in cards if c.type == "asset"}
    exts = {e.lower() for e in cfg["asset_ext"]}
    unreg = []
    for d in cfg["asset_dirs"]:
        base = root / d
        if not base.is_dir():
            continue
        for p in sorted(base.rglob("*")):
            r = rel(root, p)
            if p.is_file() and p.suffix.lower() in exts and not ignored(p.name, cfg["asset_ignore"]) \
                    and not ignored(r, cfg["asset_ignore"]) and r not in registered:
                unreg.append(r)
    for r in unreg[:30]:
        warns.append(f"unregistered asset: {r}  (python .ai/kb.py new asset \"{r}\")")
    if len(unreg) > 30:
        warns.append(f"... +{len(unreg) - 30} more unregistered assets")
    missing = []
    if coverage:
        cov = Path(coverage) if Path(coverage).is_absolute() else root / coverage
        pat = re.compile(cfg["id_pattern"])
        target = "\n".join(c.text for c in cards) + now_text + read(root / ".ai" / "INTENT.md")
        idir = root / ".ai" / "intent"
        if idir.is_dir():
            target += "".join(read(q) for q in sorted(idir.rglob("*.md")))
        for d in cfg["search_dirs"]:
            for p, _ in iter_sources(root, {**cfg, "search_dirs": [d]}, "docs"):
                target += read(p)
        have = set(pat.findall(target))
        first = {}
        files = [cov] if cov.is_file() else sorted(q for q in cov.rglob("*") if q.is_file())
        for q in files:
            if q.suffix.lower() not in {e.lower() for e in cfg["text_ext"]}:
                continue
            for i, ln in enumerate(read(q).splitlines(), 1):
                for tok in pat.findall(ln):
                    if tok not in have and tok not in first:
                        first[tok] = f"{rel(root, q)}:{i}"
        missing = sorted(first.items())
    for e in errs:
        print("ERROR " + e)
    for w in warns:
        print("WARN  " + w)
    if coverage:
        for tok, where in missing:
            print(f"MISSING {tok}  (first seen {where})")
        print(f"coverage: {len(missing)} id(s) in {coverage} not found in cards/NOW/INTENT/search_dirs")
    print(f"kb check: {len(cards)} card(s), {len(errs)} error(s), {len(warns)} warning(s)")
    return 1 if errs or (coverage and missing) or (strict and warns) else 0


# ---------------------------------------------------------------- wrapup
def wrapup(root: Path, cfg: dict) -> int:
    rep = root / ".ai" / "archive" / "reports"
    last = sorted(rep.glob("*.md")) if rep.is_dir() else []
    since = ""
    if last:
        m = re.match(r"(\d{4})(\d{2})(\d{2})", last[-1].stem)
        since = f"{m.group(1)}-{m.group(2)}-{m.group(3)}" if m else dt.date.fromtimestamp(last[-1].stat().st_mtime).isoformat()
    cards = [c for c in load_cards(root) if c.id and (not since or c.updated >= since)]
    now = dt.datetime.now()
    kr = cfg["lang"] == "kr"
    out = [f"# Wrap-up {now.strftime('%Y-%m-%d %H:%M')} " + ("(초안: kb.py wrapup, 검토 후 다듬기)" if kr else "(draft: kb.py wrapup; review and edit)"),
           "", ("> 범위: " if kr else "> Range: ") + (f"{since} 이후 갱신된 카드 {len(cards)}개" if kr else f"{len(cards)} card(s) updated since {since}")
           if since else ("> 범위: 전체" if kr else "> Range: all"), "", "## NOW", read(root / ".ai" / "NOW.md").strip() or "-"]
    for t in TYPES:
        g = [c for c in cards if c.type == t]
        if g:
            out += ["", f"## {t}"] + [f"- [[{c.id}]] {c.title} · {c.status} · {c.updated}" for c in g]
    try:
        args = ["git", "log", "--oneline", "-n", "30"] + ([f"--since={since}"] if since else [])
        g = subprocess.run(args, cwd=root, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=10)
        if g.returncode == 0 and g.stdout.strip():
            out += ["", "## commits"] + [f"- {l}" for l in g.stdout.strip().splitlines()]
    except (OSError, subprocess.SubprocessError):
        pass
    p = rep / f"{now.strftime('%Y%m%d-%H%M')}.md"
    write(p, "\n".join(out) + "\n")
    print(f"wrote {rel(root, p)} ({len(cards)} card(s))")
    return 0


# ---------------------------------------------------------------- hooks
def strip_comments(text: str) -> str:
    return "\n".join(l for l in text.splitlines() if not l.strip().startswith("<!--"))


def hook_start(root: Path, cfg: dict) -> int:
    try:
        if index_stale(root):
            build(root, cfg, quiet=True)
        m = MSG[cfg["lang"]]
        now = strip_comments(read(root / ".ai" / "NOW.md")).strip() or m["no_now"]
        idx = strip_comments(read(root / ".ai" / "INDEX.md")).strip()
        idx = "\n".join(l for l in idx.splitlines() if not l.startswith("# INDEX"))
        out = [m["start_now"], now, "", m["start_index"], idx or "-"]
        if (root / ".ai" / "BLOCKED.md").exists():
            out += ["", m["start_blocked"]]
        print("\n".join(out))
    except Exception as e:  # a hook must never break the session
        print(f"[kb] hook-start error: {e}", file=sys.stderr)
    return 0


def hook_build(root: Path, cfg: dict) -> int:
    try:
        raw = sys.stdin.read() if not sys.stdin.isatty() else ""
        data = json.loads(raw) if raw.strip() else {}
        ti = data.get("tool_input") or {}
        fp = ti.get("file_path") or ti.get("path") or ti.get("notebook_path") or ""
        if not fp:
            return 0
        p = Path(fp)
        p = p if p.is_absolute() else root / p
        r = rel(root, p)
        if r.startswith(".ai/kb/") or r == ".ai/NOW.md":
            build(root, cfg, quiet=True)
    except Exception as e:
        print(f"[kb] hook-build error: {e}", file=sys.stderr)
    return 0


# ---------------------------------------------------------------- main
def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--root", default=None, help="project root (default: parent of the .ai folder holding kb.py)")
    sub = ap.add_subparsers(dest="cmd")
    sub.add_parser("build")
    s = sub.add_parser("search")
    s.add_argument("words", nargs="+")
    s.add_argument("-k", type=int, default=5)
    s.add_argument("--scope", choices=["all", "cards", "docs", "archive", "graph"], default="all")
    s.add_argument("--type", choices=list(TYPES), default=None)
    s.add_argument("--tag", default=None)
    n = sub.add_parser("new")
    n.add_argument("type")
    n.add_argument("path", nargs="?")
    n.add_argument("--id", default=None)
    n.add_argument("--title", default=None)
    n.add_argument("--tags", default="")
    n.add_argument("--related", default="")
    c = sub.add_parser("check")
    c.add_argument("--coverage", default=None)
    c.add_argument("--strict", action="store_true", help="warnings also fail (exit 1)")
    sub.add_parser("wrapup")
    sub.add_parser("hook-start")
    sub.add_parser("hook-build")
    a = ap.parse_args(argv)
    root = find_root(a.root)
    cfg = load_cfg(root)
    if a.cmd == "build":
        build(root, cfg)
        return 0
    if a.cmd == "search":
        return search(root, cfg, a.words, a.k, a.scope, a.type, a.tag)
    if a.cmd == "new":
        return new(root, cfg, a.type, a.path, a.id, a.title, a.tags, a.related)
    if a.cmd == "check":
        return check(root, cfg, a.coverage, a.strict)
    if a.cmd == "wrapup":
        return wrapup(root, cfg)
    if a.cmd == "hook-start":
        return hook_start(root, cfg)
    if a.cmd == "hook-build":
        return hook_build(root, cfg)
    ap.print_help()
    return 2


if __name__ == "__main__":
    sys.exit(main())
